CREATE OR REPLACE FUNCTION public.check_video_tags_limit()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
 perform 1 from public.musician_videos where id=new.video_id for update;
 if (select count(*) from public.musician_video_tags where video_id=new.video_id)>=10 then raise exception 'A video cannot have more than 10 tags'; end if;
 return new;
end $function$

CREATE OR REPLACE FUNCTION app_private.assign_band_owner()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_id bigint;
begin
 if auth.uid() is not null then
 select id into v_id from public.musicians where user_id=auth.uid();
 if v_id is null then raise exception 'Musician profile required'; end if;
 insert into public.band_members(band_id,musician_id,member_role) values(new.id,v_id,'owner');
 end if;
 return new;
end $function$

CREATE OR REPLACE FUNCTION public.leave_band(p_band_id bigint)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_id bigint; v_role text;
begin
 if auth.uid() is null then raise exception 'Authentication required' using errcode='42501'; end if;
 perform 1 from public.bands where id=p_band_id for update;
 select id into v_id from public.musicians where user_id=auth.uid();
 select member_role into v_role from public.band_members where band_id=p_band_id and musician_id=v_id;
 if not found then raise exception 'You are not a member of this band'; end if;
 if v_role='owner' and (select count(*) from public.band_members where band_id=p_band_id and member_role='owner')<=1 then raise exception 'Cannot leave: you are the only owner of this band'; end if;
 delete from public.band_members where band_id=p_band_id and musician_id=v_id;
end $function$

CREATE OR REPLACE FUNCTION public.update_band_member_role(p_band_id bigint, p_musician_id bigint, p_member_role text DEFAULT NULL::text, p_role_id bigint DEFAULT NULL::bigint, p_custom_label text DEFAULT NULL::text)
 RETURNS band_members
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_old public.band_members;
begin
 if auth.uid() is null or not app_private.can_manage_band(p_band_id) then raise exception 'Only owner or admin may manage members' using errcode='42501'; end if;
 perform 1 from public.bands where id=p_band_id for update;
 select * into v_old from public.band_members where band_id=p_band_id and musician_id=p_musician_id;
 if not found then raise exception 'Band member not found' using errcode='P0002'; end if;
 return public.add_band_member(p_band_id,p_musician_id,coalesce(p_member_role,v_old.member_role),coalesce(p_role_id,v_old.role_id),coalesce(p_custom_label,v_old.custom_label));
end $function$

CREATE OR REPLACE FUNCTION public.update_musician_profile(p_user_id uuid, p_background_picture text, p_has_edu boolean, p_edu_details text, p_custom_genre text, p_genres jsonb, p_subgenres jsonb, p_roles jsonb, p_instruments jsonb, p_instrument_variants jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare v_id bigint; v_published boolean;
begin
 if auth.uid() is null or p_user_id is distinct from auth.uid() then raise exception 'Only your own profile may be updated' using errcode='42501'; end if;
 select id,is_published into v_id,v_published from public.musicians where user_id=p_user_id for update;
 if not found then raise exception 'Musician profile not found' using errcode='P0002'; end if;
 perform public.update_musician_profile(p_user_id,p_background_picture,p_has_edu,p_edu_details,p_custom_genre,v_published,
 array(select value::bigint from jsonb_array_elements_text(coalesce(p_genres,'[]'::jsonb))),
 array(select value::bigint from jsonb_array_elements_text(coalesce(p_subgenres,'[]'::jsonb))),
 array(select value::bigint from jsonb_array_elements_text(coalesce(p_roles,'[]'::jsonb))),
 array(select value::bigint from jsonb_array_elements_text(coalesce(p_instruments,'[]'::jsonb))),
 array(select value::bigint from jsonb_array_elements_text(coalesce(p_instrument_variants,'[]'::jsonb))));
 return jsonb_build_object('success',true,'musician_id',v_id);
end $function$

CREATE OR REPLACE FUNCTION public.update_musician_profile(p_user_id uuid, p_background_picture text, p_has_musical_education boolean, p_musical_education_details text, p_custom_genre text, p_is_published boolean, p_genres bigint[], p_subgenres bigint[], p_roles bigint[], p_instruments bigint[], p_instrument_variants bigint[])
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
 if auth.uid() is null or p_user_id is distinct from auth.uid() then raise exception 'Only your own profile may be updated' using errcode='42501'; end if;
 perform 1 from public.musicians where user_id=p_user_id for update;
 if not found then raise exception 'Musician profile not found' using errcode='P0002'; end if;
 update public.musicians set background_picture=p_background_picture,has_musical_education=coalesce(p_has_musical_education,false),musical_education_details=case when p_has_musical_education then nullif(btrim(p_musical_education_details),'') else null end,custom_genre=p_custom_genre,is_published=coalesce(p_is_published,false) where user_id=p_user_id;
 delete from public.musician_genres where musician_id=p_user_id;
 insert into public.musician_genres(musician_id,genre_id) select p_user_id,x from (select distinct unnest(p_genres) x) s where x is not null;
 delete from public.musician_subgenres where musician_id=p_user_id;
 insert into public.musician_subgenres(musician_id,subgenre_id) select p_user_id,x from (select distinct unnest(p_subgenres) x) s where x is not null;
 delete from public.musician_roles where musician_id=p_user_id;
 insert into public.musician_roles(musician_id,role_id) select p_user_id,x from (select distinct unnest(p_roles) x) s where x is not null;
 delete from public.musician_instruments where musician_id=p_user_id;
 insert into public.musician_instruments(musician_id,instrument_id) select p_user_id,x from (select distinct unnest(p_instruments) x) s where x is not null;
 delete from public.musician_instrument_variants where musician_id=p_user_id;
 insert into public.musician_instrument_variants(musician_id,variant_id) select p_user_id,x from (select distinct unnest(p_instrument_variants) x) s where x is not null;
end $function$

CREATE OR REPLACE FUNCTION app_private.record_band_membership()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 if tg_op='DELETE' then
 insert into public.band_member_history(band_id,musician_id,joined_at,left_at,role_id,custom_label,reason)
 values(old.band_id,old.musician_id,old.joined_at,now(),old.role_id,old.custom_label,'left_or_removed');
 return old;
 end if;
 if (old.member_role,old.role_id,old.custom_label) is distinct from (new.member_role,new.role_id,new.custom_label) then
 insert into public.band_member_history(band_id,musician_id,joined_at,left_at,role_id,custom_label,reason)
 values(old.band_id,old.musician_id,old.joined_at,now(),old.role_id,old.custom_label,'role_changed');
 new.joined_at:=now();
 else
 new.joined_at:=old.joined_at;
 end if;
 return new;
end $function$

CREATE OR REPLACE FUNCTION public.remove_band_member(p_band_id bigint, p_musician_id bigint)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor text;v_target text;
begin
 if auth.uid() is null then raise exception 'Authentication required' using errcode='42501'; end if;
 perform 1 from public.bands where id=p_band_id for update;
 select bm.member_role into v_actor from public.band_members bm join public.musicians m on m.id=bm.musician_id where bm.band_id=p_band_id and m.user_id=auth.uid();
 if v_actor is null or v_actor not in ('owner','admin') then raise exception 'Only owner or admin may remove members' using errcode='42501'; end if;
 select member_role into v_target from public.band_members where band_id=p_band_id and musician_id=p_musician_id;
 if not found then raise exception 'Band member not found' using errcode='P0002'; end if;
 if v_actor='admin' and v_target<>'member' then raise exception 'Only owners may remove privileged members' using errcode='42501'; end if;
 if v_target='owner' and (select count(*) from public.band_members where band_id=p_band_id and member_role='owner')<=1 then raise exception 'Cannot remove the last owner'; end if;
 delete from public.band_members where band_id=p_band_id and musician_id=p_musician_id;
end $function$

CREATE OR REPLACE FUNCTION public.add_band_member(p_band_id bigint, p_musician_id bigint, p_member_role text DEFAULT 'member'::text, p_role_id bigint DEFAULT NULL::bigint, p_custom_label text DEFAULT NULL::text)
 RETURNS band_members
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor_role text; v_target_role text; v_new public.band_members; v_role text:=coalesce(p_member_role,'member');
begin
 if auth.uid() is null then raise exception 'Authentication required' using errcode='42501'; end if;
 perform 1 from public.bands where id=p_band_id for update;
 if not found then raise exception 'Band not found' using errcode='P0002'; end if;
 select bm.member_role into v_actor_role from public.band_members bm join public.musicians m on m.id=bm.musician_id where bm.band_id=p_band_id and m.user_id=auth.uid();
 if v_actor_role is null or v_actor_role not in ('owner','admin') then raise exception 'Only owner or admin may manage members' using errcode='42501'; end if;
 if v_role not in ('owner','admin','member') then raise exception 'Invalid member role' using errcode='22023'; end if;
 select member_role into v_target_role from public.band_members where band_id=p_band_id and musician_id=p_musician_id;
 if v_actor_role='admin' and (v_role<>'member' or coalesce(v_target_role,'member')<>'member') then raise exception 'Only owners may manage privileged roles' using errcode='42501'; end if;
 if v_target_role='owner' and v_role<>'owner' and (select count(*) from public.band_members where band_id=p_band_id and member_role='owner')<=1 then raise exception 'Cannot demote the last owner'; end if;
 insert into public.band_members(band_id,musician_id,member_role,role_id,custom_label) values(p_band_id,p_musician_id,v_role,p_role_id,p_custom_label)
 on conflict(band_id,musician_id) do update set member_role=excluded.member_role,role_id=excluded.role_id,custom_label=excluded.custom_label returning * into v_new;
 return v_new;
end $function$
